window.SCHOOL_LISTENING={"../assets/media/b3c6be0b8da06b6266cae7ee916cff735d4946b32885a484b934d5c72411c757.mp3":[{"id":"PPT_b3c6be0b8da06b62","audioId":"PPT_b3c6be0b8da06b62","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 29","duration":68.34,"cues":[{"start":0,"end":2.28,"text":"three .two","coverage":1},{"start":2.28,"end":3.14,"text":"one.","coverage":1},{"start":3.92,"end":8.42,"text":"The town hall keeps a record of how many vehicles use this road.","coverage":1},{"start":10.44,"end":11.12,"text":"two.","coverage":1},{"start":11.92,"end":16.22,"text":"His mum bought him a new car as a present for passing his exams.","coverage":1},{"start":18.44,"end":19.12,"text":"three.","coverage":1},{"start":20.02,"end":23.58,"text":"I went back to the shop to get a refund on my bus pass.","coverage":1},{"start":25.62,"end":26.24,"text":"four.","coverage":1},{"start":27.24,"end":32.6,"text":"Each year, the taxi company presents an award to its most careful driver.","coverage":1},{"start":34.8,"end":35.42,"text":"five.","coverage":1},{"start":36.44,"end":39.74,"text":"Will you promise me that you'll call as soon as your flight lands?","coverage":1},{"start":42.37,"end":42.68,"text":"six.","coverage":1},{"start":43.8,"end":48.78,"text":"The train company are going to refund the cost of my ticket because of the delays.","coverage":1},{"start":50.66,"end":51.38,"text":"seven.","coverage":1},{"start":52.52,"end":58.28,"text":"We want to record the traffic noise around the city to see how high it actually is.","coverage":1},{"start":59.78,"end":60.5,"text":"eight.","coverage":1},{"start":61.4,"end":64.82,"text":"This car is the most comfortable you will ever drive.","coverage":1},{"start":65.26,"end":66.38,"text":"That's a promise.","coverage":1}],"file":"02ee0fcf1d9bd90d7055.js","track":0,"media":"../assets/media/b3c6be0b8da06b6266cae7ee916cff735d4946b32885a484b934d5c72411c757.mp3"}],"../assets/media/2eb6fdcb2760c4275faa44cc2634b666e7bbaa8eef13dd75d87b863f34ecf66d.mp3":[{"id":"PPT_2eb6fdcb2760c427","audioId":"PPT_2eb6fdcb2760c427","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 23","duration":33.72,"cues":[{"start":0,"end":1.84,"text":"Unit three,","coverage":1},{"start":2.5,"end":4.14,"text":"three .one.","coverage":1},{"start":4.56,"end":5.36,"text":"one.","coverage":1},{"start":6.22,"end":10,"text":"There has been a decrease in the number of bus passengers this year.","coverage":1},{"start":11.86,"end":12.54,"text":"two.","coverage":1},{"start":13.48,"end":17.36,"text":"The traffic will decrease after they have finished repairing the road.","coverage":1},{"start":19.46,"end":20.26,"text":"three.","coverage":1},{"start":21.26,"end":24.92,"text":"Most cities don't permit cyclists to ride on the pavement.","coverage":1},{"start":26.86,"end":27.66,"text":"four.","coverage":1},{"start":27.66,"end":31.8,"text":"You need a special permit to park in the city centre.","coverage":1}],"file":"2bcb306ae4467434255e.js","track":0,"media":"../assets/media/2eb6fdcb2760c4275faa44cc2634b666e7bbaa8eef13dd75d87b863f34ecf66d.mp3"}],"../assets/media/25455e2aa0d888995b95e5767ae2edc2edb36b5f6a2ffecf850985eb856af6b2.mp3":[{"id":"PPT_25455e2aa0d88899","audioId":"PPT_25455e2aa0d88899","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 64","duration":176.12,"cues":[{"start":0,"end":1.54,"text":"three .four","coverage":1},{"start":1.54,"end":4.98,"text":"And how can we solve these problems?","coverage":1},{"start":5.64,"end":7.88,"text":"Let's think again about traffic lights.","coverage":1},{"start":8.72,"end":10.58,"text":"Because of improvements in technology,","coverage":1},{"start":11.24,"end":16.08,"text":"modern traffic signals can measure how quickly the vehicles are moving along the roads,","coverage":1},{"start":16.7,"end":18.46,"text":"or see whether there's been a crash,","coverage":1},{"start":18.84,"end":22,"text":"and send this information back to a control center.","coverage":1},{"start":22,"end":23.94,"text":"I've heard about this.","coverage":1},{"start":24.44,"end":26.54,"text":"It means that the traffic controllers,","coverage":1},{"start":26.9,"end":28.7,"text":"either human or computer,","coverage":1},{"start":29.12,"end":32.42,"text":"can check for changes in traffic throughout the day,","coverage":1},{"start":32.78,"end":37.5,"text":"and figure out the best way to organize the signals to keep everything moving.","coverage":1},{"start":38.24,"end":38.66,"text":"Yes.","coverage":1},{"start":39.18,"end":45.34,"text":"They don't have to follow the same fixed timings for the lights all day long, like signals used to do.","coverage":1},{"start":45.34,"end":49.82,"text":"And although it's expensive to put in these signals across a whole city,","coverage":1},{"start":50.36,"end":52.28,"text":"it's far better than doing nothing.","coverage":1},{"start":53.62,"end":53.64,"text":"Technology,","coverage":1},{"start":54.08,"end":55.66,"text":"where would we be without it?","coverage":1},{"start":56.3,"end":56.94,"text":"Exactly.","coverage":1},{"start":58,"end":60.92,"text":"Which reminds me of another way to reduce traffic.","coverage":1},{"start":61.76,"end":64.44,"text":"Businesses replacing their vehicles with drones.","coverage":1},{"start":65.16,"end":65.66,"text":"Okay,","coverage":1},{"start":66.14,"end":66.86,"text":"tell me more.","coverage":1},{"start":66.86,"end":72.58,"text":"Some tasks city governments need to do, such as checking electricity lines,","coverage":1},{"start":73.18,"end":78.06,"text":"don't necessarily need to be carried out by a single person arriving in a big vehicle.","coverage":1},{"start":78.9,"end":83,"text":"A drone with a camera could send this information to engineers,","coverage":1},{"start":83.48,"end":85.74,"text":"who only need to go out if there is a problem.","coverage":1},{"start":86.6,"end":90.36,"text":"Think of how many work vans this could take off the roads every day.","coverage":1},{"start":90.72,"end":92.6,"text":"And delivery vans.","coverage":1},{"start":92.6,"end":94.78,"text":"That's another good example.","coverage":1},{"start":95.52,"end":96.56,"text":"In some cities,","coverage":1},{"start":97.1,"end":101.8,"text":"businesses can use drones to deliver small parcels, which is fantastic.","coverage":1},{"start":102.32,"end":104.96,"text":"It means even fewer vehicles on the roads.","coverage":1},{"start":105.7,"end":110.04,"text":"What would you say to people who refuse to give up driving their cars ever?","coverage":1},{"start":110.5,"end":114.84,"text":"I honestly think people should try to avoid driving as much as possible.","coverage":1},{"start":115.36,"end":118.64,"text":"But if they can't, they should consider their behavior.","coverage":1},{"start":118.64,"end":122.42,"text":"It's not just bad parking that causes traffic issues.","coverage":1},{"start":123.14,"end":126.08,"text":"Everyone needs to be a lot more responsible as drivers.","coverage":1},{"start":126.9,"end":127.54,"text":"In what way?","coverage":1},{"start":128.24,"end":130.26,"text":"When people get behind the steering wheel,","coverage":1},{"start":130.62,"end":132.98,"text":"they often become less helpful than normal.","coverage":1},{"start":133.68,"end":136.3,"text":"Like when someone is turning into a side street,","coverage":1},{"start":136.88,"end":142.22,"text":"that often means driving across the other lane, past vehicles going in the opposite direction.","coverage":1},{"start":142.22,"end":143.12,"text":"If","coverage":1},{"start":143.12,"end":143.4,"text":"no","coverage":1},{"start":143.4,"end":146.7,"text":"one slows down to let in the person who wants to turn,","coverage":1},{"start":147.14,"end":149.74,"text":"the traffic gets worse and worse behind them.","coverage":1},{"start":150.16,"end":157.48,"text":"Even more so if someone stops in traffic with their car across the side street that person wants to turn into.","coverage":1},{"start":158.16,"end":158.48,"text":"Ah!","coverage":1},{"start":159.06,"end":163.42,"text":"Listeners, if that doesn't annoy you as well, you're a better person than me.","coverage":1},{"start":164.28,"end":165.12,"text":"Me too!","coverage":1},{"start":165.6,"end":170.62,"text":"Please, everyone, stop and give people enough space to turn into side streets!","coverage":1},{"start":170.62,"end":171.58,"text":"Mark,","coverage":1},{"start":171.98,"end":173.32,"text":"thanks for joining me.","coverage":1},{"start":173.7,"end":174.24,"text":"Thank you.","coverage":1}],"file":"37461c2c02bda6a5ba14.js","track":0,"media":"../assets/media/25455e2aa0d888995b95e5767ae2edc2edb36b5f6a2ffecf850985eb856af6b2.mp3"}],"../assets/media/e1fae6e42cbed46169bdb85fa7160ae164fb1f1e0e8fbf0427e7e2958b73041f.mp3":[{"id":"PPT_e1fae6e42cbed461","audioId":"PPT_e1fae6e42cbed461","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 60","duration":157.81,"cues":[{"start":0,"end":1.84,"text":"three .three","coverage":1},{"start":1.84,"end":5.84,"text":"Do you live, study, or work in a large city?","coverage":1},{"start":6.44,"end":10.58,"text":"Are the traffic problems so serious they often cause you to be late?","coverage":1},{"start":11.1,"end":13.6,"text":"If so, you're not alone.","coverage":1},{"start":14.78,"end":20.42,"text":"Over the past century, there's been a huge increase in the traffic that moves through our cities.","coverage":1},{"start":20.42,"end":30.02,"text":"And if, as the United Nations predicts, 70 % of the world's population will be living in cities by the year 2050,","coverage":1},{"start":30.84,"end":35.42,"text":"what will we do when the amount of traffic increases even more?","coverage":1},{"start":36.04,"end":37.14,"text":"How will we cope?","coverage":1},{"start":37.72,"end":39.82,"text":"Can we do anything to control it?","coverage":1},{"start":40.66,"end":43.68,"text":"With me in today's podcast is Mark Knowling,","coverage":1},{"start":44.04,"end":47.14,"text":"an expert in transport and traffic management.","coverage":1},{"start":47.14,"end":48.18,"text":"Mark,","coverage":1},{"start":48.5,"end":50.38,"text":"what's happening in our cities?","coverage":1},{"start":51.24,"end":54.06,"text":"It's a fact that, in a great many cities,","coverage":1},{"start":54.4,"end":57.64,"text":"the traffic is more extreme than ever before.","coverage":1},{"start":58.52,"end":65.04,"text":"The primary cause is that there are so many private vehicles on the roads carrying only one or two people.","coverage":1},{"start":65.84,"end":71.58,"text":"Compare this to buses, which are by far the most efficient option for reducing traffic,","coverage":1},{"start":72,"end":76.32,"text":"as they can transport huge numbers of passengers at the same time.","coverage":1},{"start":76.32,"end":82.62,"text":"But people don't seem to want to leave their expensive cars at home and take the bus instead.","coverage":1},{"start":83.68,"end":86.96,"text":"What other factors influence how well traffic flows?","coverage":1},{"start":87.82,"end":88.22,"text":"Well,","coverage":1},{"start":88.56,"end":94.84,"text":"a crash on a busy city center road can have a huge impact on all the other roads close by.","coverage":1},{"start":95.54,"end":101.32,"text":"Or someone parking their vehicle so that it blocks the traffic, even if only for a minute or so.","coverage":1},{"start":101.32,"end":103.44,"text":"A delivery driver, for example,","coverage":1},{"start":103.88,"end":106.36,"text":"can cause trouble for everyone behind them.","coverage":1},{"start":107.42,"end":113.56,"text":"Even something small like that means everyone's journey suddenly becomes more difficult than they expected.","coverage":1},{"start":114.2,"end":117.04,"text":"It's the most annoying thing in the world.","coverage":1},{"start":117.74,"end":120.2,"text":"Should we blame car drivers for all this,","coverage":1},{"start":121.06,"end":122.6,"text":"It's not always their fault.","coverage":1},{"start":123.38,"end":128.06,"text":"Traditional traffic signals in so many of our cities are years old now.","coverage":1},{"start":128.06,"end":131.96,"text":"They always change color after a certain number of seconds.","coverage":1},{"start":132.66,"end":137.74,"text":"That's not a sensible idea when we consider the number of vehicles driving today.","coverage":1},{"start":138.32,"end":139.02,"text":"For instance,","coverage":1},{"start":139.38,"end":142.06,"text":"a driver might see a green light and continue,","coverage":1},{"start":142.46,"end":146.24,"text":"but immediately join a long line of vehicles that isn't moving.","coverage":1},{"start":147.06,"end":149.34,"text":"Then, when the lights turn back to red,","coverage":1},{"start":149.76,"end":152.08,"text":"they are parked across a busy junction.","coverage":1},{"start":152.78,"end":156,"text":"That usually leads to all sorts of delays over the day.","coverage":1}],"file":"3af3057e400a7001c964.js","track":0,"media":"../assets/media/e1fae6e42cbed46169bdb85fa7160ae164fb1f1e0e8fbf0427e7e2958b73041f.mp3"}],"../assets/media/2bc1571c16175f77c84196fde84016072bd863dc9af91a56594cb5cd5716eb71.mp3":[{"id":"PPT_2bc1571c16175f77","audioId":"PPT_2bc1571c16175f77","title":"Book 3 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 104","duration":93.15,"cues":[{"start":0,"end":1.52,"text":"three .seven","coverage":1},{"start":2.1,"end":5.54,"text":"Now I'd like to share some possible solutions.","coverage":1},{"start":6.56,"end":8.1,"text":"First, to improve safety,","coverage":1},{"start":8.7,"end":15.82,"text":"I'd suggest that police officers give big fines to drivers who break the law by driving in a cycle lane.","coverage":1},{"start":16.86,"end":23.54,"text":"Also, I'd like to see wider cycle lanes to allow more bicycles to pass at the same time.","coverage":1},{"start":24.4,"end":29.94,"text":"We should also add cycle lanes to busy streets which don't have them yet.","coverage":1},{"start":30.8,"end":36.64,"text":"These proposals would prevent cars from hitting cyclists and would save lives.","coverage":1},{"start":37.56,"end":39.28,"text":"As for the issue of storage,","coverage":1},{"start":39.82,"end":45.46,"text":"I think that city parking garages ought to create special parking sections for bicycles.","coverage":1},{"start":46.68,"end":51.1,"text":"This would keep bicycles safe and dry while people are working.","coverage":1},{"start":52.38,"end":52.92,"text":"Finally,","coverage":1},{"start":53.4,"end":53.98,"text":"convenience.","coverage":1},{"start":53.98,"end":55.52,"text":"In my opinion,","coverage":1},{"start":55.86,"end":59.64,"text":"we should make it easier to take bicycles on public transport.","coverage":1},{"start":60.18,"end":64.2,"text":"For example, we could put cycle racks on the outside of buses.","coverage":1},{"start":64.62,"end":68.7,"text":"That way, people wouldn't have to cycle at night or in bad weather.","coverage":1},{"start":69.42,"end":76.18,"text":"And people who live far from work could cycle part of the way to work and take public transport the rest of the way.","coverage":1},{"start":76.76,"end":77.6,"text":"As a result,","coverage":1},{"start":77.92,"end":80.08,"text":"more people could cycle to work.","coverage":1},{"start":80.96,"end":81.54,"text":"Well,","coverage":1},{"start":81.92,"end":84.16,"text":"thank you again for listening to my ideas.","coverage":1},{"start":84.96,"end":91.24,"text":"I hope this is the beginning of a conversation about how we can make this a great city for cyclists.","coverage":1}],"file":"3c86541ace40f4e6d1eb.js","track":0,"media":"../assets/media/2bc1571c16175f77c84196fde84016072bd863dc9af91a56594cb5cd5716eb71.mp3"}],"../assets/media/c4248e7c6ce61ce13b0573a685194626ef4e31ea017ff9f17501d97a65a3ead1.mp3":[{"id":"PPT_c4248e7c6ce61ce1","audioId":"PPT_c4248e7c6ce61ce1","title":"Book 3 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 98","duration":149.84,"cues":[{"start":2.1,"end":2.44,"text":"Hello","coverage":1},{"start":2.44,"end":3.46,"text":"everyone.","coverage":1},{"start":3.94,"end":5.68,"text":"Thank you for being here today.","coverage":1},{"start":6.24,"end":9.58,"text":"Welcome to the first meeting of Wheels to Work.","coverage":1},{"start":10.18,"end":15.42,"text":"As you know, the goal of this group is to make our city more bicycle -friendly.","coverage":1},{"start":16.12,"end":16.8,"text":"Specifically,","coverage":1},{"start":17.24,"end":21.16,"text":"we'd like to make it easier for people to cycle to work.","coverage":1},{"start":21.78,"end":26.96,"text":"Cycling to work is good for the environment and it provides great exercise.","coverage":1},{"start":27.62,"end":28.72,"text":"And personally,","coverage":1},{"start":29.06,"end":30.52,"text":"I think it's a lot of fun.","coverage":1},{"start":31.36,"end":39,"text":"I'm hoping that we can work together to solve the problems which can make it difficult for city residents to cycle to work.","coverage":1},{"start":39.74,"end":45.94,"text":"Today, I'm going to talk about a few of those problems and share some ideas for solving them.","coverage":1},{"start":46.7,"end":49.28,"text":"So, the biggest issue is safety.","coverage":1},{"start":50.16,"end":54.32,"text":"A lot of people would love to cycle to work, but they're scared.","coverage":1},{"start":54.84,"end":57.22,"text":"They feel that it's just too dangerous.","coverage":1},{"start":58.08,"end":67.56,"text":"This is because there's a lot of traffic during rush hour when most people drive to or from work and there's very little space for cyclists.","coverage":1},{"start":67.8,"end":74.8,"text":"Many of the cycle lanes we have are too narrow and some of the busiest streets don't even have cycle lanes.","coverage":1},{"start":75.84,"end":80.16,"text":"What's more, many drivers don't have respect for cyclists.","coverage":1},{"start":80.42,"end":84.8,"text":"Cars sometimes even drive in the cycle lanes to pass other cars.","coverage":1},{"start":85.58,"end":88.02,"text":"Of course, if a car hits a bicycle,","coverage":1},{"start":88.44,"end":91.64,"text":"it's going to injure or even kill the cyclist.","coverage":1},{"start":92.3,"end":94.3,"text":"A second issue is storage.","coverage":1},{"start":94.82,"end":99.82,"text":"Many people don't have a safe place to put their bicycles while they're at work.","coverage":1},{"start":100.52,"end":103.76,"text":"They worry that if they leave their bicycle outside,","coverage":1},{"start":104.08,"end":105,"text":"it'll get stolen.","coverage":1},{"start":105.78,"end":110.6,"text":"Also, it'll get wet when it rains and get damaged over time.","coverage":1},{"start":111.44,"end":116.98,"text":"A third problem is that for some people, cycling to work isn't convenient.","coverage":1},{"start":117.5,"end":124.78,"text":"Maybe they live far from their job or maybe they sometimes work late and don't want to cycle home in the dark.","coverage":1},{"start":125.58,"end":129.24,"text":"And a lot of people don't like to cycle in the rain.","coverage":1},{"start":130,"end":133.88,"text":"What if you cycle to work and then later it starts raining?","coverage":1},{"start":134.76,"end":136.16,"text":"From my own experience,","coverage":1},{"start":136.52,"end":140.46,"text":"I can tell you that it's pretty terrible to ride home during a storm.","coverage":1},{"start":141.36,"end":141.78,"text":"So,","coverage":1},{"start":142.24,"end":144.4,"text":"those are three of the biggest issues,","coverage":1},{"start":144.86,"end":145.38,"text":"safety,","coverage":1},{"start":145.96,"end":147.86,"text":"storage and convenience.","coverage":1}],"file":"a942701ddb54264556fb.js","track":0,"media":"../assets/media/c4248e7c6ce61ce13b0573a685194626ef4e31ea017ff9f17501d97a65a3ead1.mp3"}],"../assets/media/b7ed356f35ab91c75f4452b177dc42ea66fa5370cf4b3a2f987f862e5da699f2.mp3":[{"id":"PPT_b7ed356f35ab91c7","audioId":"PPT_b7ed356f35ab91c7","title":"Book 3 · Unit 3 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 193","duration":115.67,"cues":[{"start":0,"end":1.52,"text":"three .eight","coverage":1},{"start":1.52,"end":4.98,"text":"I'm really surprised by these statistics.","coverage":1},{"start":5.54,"end":8.64,"text":"I didn't know that eating while driving is dangerous.","coverage":1},{"start":9.46,"end":12.32,"text":"I don't think the government should do anything about it.","coverage":1},{"start":12.76,"end":13.18,"text":"Personally,","coverage":1},{"start":13.64,"end":18.84,"text":"I eat fast food in my car a few times a week and I've never had an accident.","coverage":1},{"start":19.54,"end":23.26,"text":"And I'm not convinced that driving while eating is a big problem.","coverage":1},{"start":23.98,"end":25.74,"text":"Have you ever eaten while driving?","coverage":1},{"start":25.74,"end":27.5,"text":"No, I haven't.","coverage":1},{"start":27.88,"end":30.18,"text":"We should take this really seriously.","coverage":1},{"start":30.94,"end":34.48,"text":"I think it would be better if they closed drive -through restaurants.","coverage":1},{"start":35,"end":40.1,"text":"This is because they only encourage drivers to buy food and eat it while they drive.","coverage":1},{"start":40.64,"end":44.84,"text":"How can you focus on the road if you're holding a big burger in your hand?","coverage":1},{"start":45.36,"end":47.14,"text":"It seems dangerous to me.","coverage":1},{"start":47.6,"end":48.56,"text":"What do you think?","coverage":1},{"start":48.88,"end":50.26,"text":"I completely agree.","coverage":1},{"start":50.26,"end":55.92,"text":"I think it would be much better if drivers weren't allowed to eat or drink while they drive.","coverage":1},{"start":56.52,"end":57.94,"text":"From my own experience,","coverage":1},{"start":58.26,"end":60.64,"text":"I can tell you that it can be very dangerous.","coverage":1},{"start":61.5,"end":62.16,"text":"Last week,","coverage":1},{"start":62.54,"end":65.82,"text":"I bought some coffee and something to eat on the way to work.","coverage":1},{"start":66.38,"end":67.28,"text":"As I was driving,","coverage":1},{"start":67.6,"end":71.88,"text":"I had to brake suddenly and I spilled hot coffee over my legs.","coverage":1},{"start":72.5,"end":74.42,"text":"I almost lost control of the car.","coverage":1},{"start":75.06,"end":79.38,"text":"I think the police should give heavy fines if they see someone doing it.","coverage":1},{"start":79.38,"end":81.6,"text":"Okay, I understand.","coverage":1},{"start":82.28,"end":86.28,"text":"But it might be very difficult for the police to see drivers eating,","coverage":1},{"start":86.78,"end":88.76,"text":"especially if they're driving fast.","coverage":1},{"start":89.58,"end":94.82,"text":"The best thing would be to have more cameras on the roads to record what drivers are doing.","coverage":1},{"start":95.66,"end":100.52,"text":"The reason for this is the police can check the videos to see who's eating,","coverage":1},{"start":101.02,"end":102.86,"text":"who's texting and so on.","coverage":1},{"start":103.48,"end":110.56,"text":"Then I'd suggest that the police give the drivers points on their licence If the driver has a lot of points,","coverage":1},{"start":111.24,"end":113.7,"text":"the police should take their car away for a few months.","coverage":1}],"file":"e9ecf81cc0aefefa86ba.js","track":0,"media":"../assets/media/b7ed356f35ab91c75f4452b177dc42ea66fa5370cf4b3a2f987f862e5da699f2.mp3"}],"../assets/media/e5869727902f1de10d6c2d9a82884b6b9a00cc0090f97628a3a2d3eceffcdd29.mp3":[{"id":"PPT_e5869727902f1de1","audioId":"PPT_e5869727902f1de1","title":"Book 3 · Unit 3 · LS · LANGUAGE DEVELOPMENT","subtitle":"LANGUAGE DEVELOPMENT · source slide 154","duration":70.03,"cues":[{"start":0,"end":2.22,"text":"three .five","coverage":1},{"start":2.22,"end":3.24,"text":"one","coverage":1},{"start":4,"end":7.46,"text":"The course was a lot more challenging than I expected.","coverage":1},{"start":10.12,"end":10.84,"text":"two","coverage":1},{"start":11.76,"end":16.3,"text":"We can see that by far the most affordable form of transport is walking.","coverage":1},{"start":18.94,"end":19.66,"text":"three","coverage":1},{"start":20.76,"end":26.24,"text":"The risks of driving a car are considerably more significant than those of flying.","coverage":1},{"start":28.52,"end":29.36,"text":"four","coverage":1},{"start":30.22,"end":35.16,"text":"For me, flying is much more comfortable than travelling by train.","coverage":1},{"start":38.06,"end":43.18,"text":"five Taking a train is definitely more relaxing than driving.","coverage":1},{"start":46.02,"end":52.54,"text":"six Using the underground is a lot faster than travelling by bus at rush hour.","coverage":1},{"start":54.4,"end":60.2,"text":"seven Driving is considerably more expensive than walking.","coverage":1},{"start":63.14,"end":63.7,"text":"eight","coverage":1},{"start":64.26,"end":68.14,"text":"Cycling is absolutely the healthiest form of transport.","coverage":1}],"file":"fbde63a26aa690b8fb5e.js","track":0,"media":"../assets/media/e5869727902f1de10d6c2d9a82884b6b9a00cc0090f97628a3a2d3eceffcdd29.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 Which types of transport do you frequently use? Why?Possible answer: I usually take the bus because it is affordable and nearby.","slide":4,"shape":"15","bookPage":"60"},{"text":"2 In your country, what is the most common type of transport that people use? How environmentally-friendly is it?Possible answer: Many people use cars; sharing a car or using a bus can reduce vehicles.","slide":4,"shape":"17","bookPage":"60"},{"text":"1 What parts of the world can you see in the photos? What forms of transport are shown? What do you think the video will tell you about them?Possible answer: I can see London and other cities. The photos show road vehicles, bicycles, a suspended railway and a modern train. The video may explain how different places make transport more sustainable.","slide":6,"shape":"28","bookPage":"60"},{"text":"2 Which of these forms of transport is the most/least environmentally-friendly?Possible answer: Cycling probably has the lowest direct emissions. A car carrying only one person is likely to cause more pollution per passenger.","slide":6,"shape":"29","bookPage":"60"},{"text":"3 How can people make their travel less damaging to the environment?Possible answer: Walk or cycle short journeys, share journeys, or use public transport.","slide":6,"shape":"30","bookPage":"60"},{"text":"1  A camera can identify a car by its registration number.","slide":13,"shape":"8","bookPage":"60"},{"text":"2  Heavy traffic causes congestion in the city centre.","slide":13,"shape":"9","bookPage":"60"},{"text":"3  An electromagnet needs electricity to create a magnetic effect.","slide":13,"shape":"10","bookPage":"60"},{"text":"4  Reducing each vehicle’s carbon emission can help cut pollution.","slide":13,"shape":"11","bookPage":"60"},{"text":"5  A transport system should be affordable and sustainable.","slide":13,"shape":"12","bookPage":"60"},{"text":"Heavy transport use around the world is a cause of (1) climate change. Carbon emissions\ncreate pollution as a result of people using (2) fossil fuels to power their vehicles.","slide":16,"shape":"6","bookPage":"61"},{"text":"Many cities are trying to find ways to make (3) short journeys more environmentally-friendly.\nThis can include limiting the amount of transport in a (4) city centre, or encouraging\npeople to take advantage of (5) bike travel / cycling — an increasingly safe and popular option.","slide":16,"shape":"7","bookPage":"61"},{"text":"It is more difficult to control the damage that (6) longer journeys do to the environment.","slide":16,"shape":"8","bookPage":"61"},{"text":"4  In Batumi, people often travel up hills by electric c able car.","slide":20,"shape":"7","bookPage":"61"},{"text":"5  Older forms of transport, such as the t ram systems in Prague and Melbourne,\ncan be environmentally-friendly.","slide":20,"shape":"8","bookPage":"61"},{"text":"1 Which of the forms of transport would you like to travel on? Why?Possible answer: I would like a cable car because I could enjoy the view and travel up a steep hill.","slide":22,"shape":"15","bookPage":"61"},{"text":"2 Which is the better option to reduce carbon emissions in city centres: congestion zones or no-drive days? Why?Possible answer: A congestion zone may change travel habits but needs good public transport.","slide":22,"shape":"17","bookPage":"61"},{"text":"1 There has been a DE-crease in the number of bus passengers this year.","slide":24,"shape":"17","bookPage":"62"},{"text":"2 The traffic will de-CREASE after they have finished repairing the road.","slide":24,"shape":"18","bookPage":"62"},{"text":"3 Most cities don’t per-MIT cyclists to ride on the pavement.","slide":25,"shape":"17","bookPage":"62"},{"text":"4 You need a special PER-mit to park in the city centre.","slide":25,"shape":"18","bookPage":"62"},{"text":"1 The town hall keeps a RE-cord of how many vehicles use this road.","slide":29,"shape":"17","bookPage":"62"},{"text":"2 His mum bought him a new car as a PRE-sent for passing his exams.","slide":29,"shape":"18","bookPage":"62"},{"text":"3 I went back to the shop to get a RE-fund on my bus pass.","slide":30,"shape":"17","bookPage":"62"},{"text":"4 Each year, the taxi company pre-SENTS an award to its most careful driver.","slide":30,"shape":"18","bookPage":"62"},{"text":"5 Will you PRO-mise me that you’ll call as soon as your flight lands?","slide":31,"shape":"16","bookPage":"62"},{"text":"6 The train company are going to re-FUND the cost of my ticket because of the delays.","slide":31,"shape":"17","bookPage":"62"},{"text":"7 We want to re-CORD the traffic noise around the city to see how high it actually is.","slide":31,"shape":"18","bookPage":"62"},{"text":"8 This car is the most comfortable you will ever drive. That’s a PRO-mise!","slide":32,"shape":"17","bookPage":"62"},{"text":"5  I don’t know how the taxi drivers in this city cope — their job seems so stressful.","slide":46,"shape":"7","bookPage":"63"},{"text":"6  The weather was so extreme this morning that I had to wait in my car for forty\nminutes before I could get out!","slide":46,"shape":"8","bookPage":"63"},{"text":"7  My primary aim as minister for transport is to improve the quality of our public\ntransport systems.","slide":46,"shape":"9","bookPage":"63"},{"text":"8  The quality of our bus routes has suffered after several years of bad management.","slide":46,"shape":"10","bookPage":"63"},{"text":"1  avoid  (v) to stay away from something or not allow yourself to do something","slide":51,"shape":"6","bookPage":"63"},{"text":"2  block  (v) to prevent movement through or past something","slide":51,"shape":"7","bookPage":"63"},{"text":"3  crash  (n) an accident in which a vehicle hits something","slide":51,"shape":"8","bookPage":"63"},{"text":"4  cope  (v) deal successfully with a difficult situation","slide":51,"shape":"9","bookPage":"63"},{"text":"5  extreme  (adj) very severe or bad","slide":51,"shape":"10","bookPage":"63"},{"text":"6  measure  (v) to discover the exact amount or size of something","slide":51,"shape":"11","bookPage":"63"},{"text":"7  management  (n) the control and organization of something","slide":51,"shape":"12","bookPage":"63"},{"text":"8  primary  (adj) more important than anything else","slide":51,"shape":"13","bookPage":"63"},{"text":"1 Which of these forms of transport do you think is the best for getting around a city? Why?Possible answer: For longer journeys, I prefer the underground; for short journeys, walking.","slide":53,"shape":"15","bookPage":"64"},{"text":"2 Which of the forms of transport is most popular in your city or town?Possible answer: Buses are popular because routes connect neighbourhoods.","slide":53,"shape":"17","bookPage":"64"},{"text":"1 In the introduction, what does the host say the podcast is about?b — The problem of traffic in cities around the world.","slide":60,"shape":"14","bookPage":"64"},{"text":"2 What does Mark say causes extreme levels of traffic in cities?c — The small number of people who travel together.","slide":61,"shape":"14","bookPage":"64"},{"text":"3 What does Mark say next?b — Even brief events can cause long delays.","slide":62,"shape":"14","bookPage":"64"},{"text":"4 What comment does Mark make about traditional traffic lights?a — They can cause traffic problems all day long.","slide":63,"shape":"14","bookPage":"64"},{"text":"Modern traffic signals: improved (1) technology helps keep the traffic flowing, or register crashes.","slide":65,"shape":"17","bookPage":"65"},{"text":"They record information and send it to a control (2) centre.","slide":65,"shape":"18","bookPage":"65"},{"text":"This is a big improvement on old signals, which constantly had the same timings on the (3) traffic lights.","slide":66,"shape":"17","bookPage":"65"},{"text":"Drones: these can be used instead of road vehicles for checking (4) electricity lines or delivering small (5) parcels, which means there are fewer vehicles in our cities.","slide":67,"shape":"17","bookPage":"65"},{"text":"Anybody who chooses to drive should think about their (6) behaviour and act more responsibly.","slide":67,"shape":"18","bookPage":"65"},{"text":"When they drive, people often become less (7) helpful to others.","slide":68,"shape":"17","bookPage":"65"},{"text":"In particular, everybody should pay more attention to drivers in the (8) opposite lane.","slide":68,"shape":"18","bookPage":"65"},{"text":"11. Why does Mark prefer buses as a way to reduce traffic?\nA. They can avoid roads used by private cars.\nB. They carry more people in each vehicle.\nC. They encourage passengers to travel at different times.","slide":71,"shape":"5","bookPage":null},{"text":"12. What point does the delivery-driver example illustrate?\nA. Drivers find city addresses harder to locate than expected.\nB. A brief obstruction can delay many other people.\nC. Delivery vehicles usually travel farther than private cars.","slide":72,"shape":"5","bookPage":null},{"text":"1 Did you injure your knee when you fell off your bicycle?Injure means to hurt or cause physical harm.","slide":85,"shape":"15","bookPage":"71"},{"text":"2 Drivers should always have respect for pedestrians and stop for them.Respect means polite behaviour towards somebody.","slide":85,"shape":"16","bookPage":"71"},{"text":"3 I got a fine for driving through a red light. It was over £50.A fine is money paid as a punishment for breaking a law.","slide":85,"shape":"17","bookPage":"71"},{"text":"4 Some people break the law by driving without a licence.Break the law means fail to obey rules.","slide":85,"shape":"18","bookPage":"71"},{"text":"5 We can prevent accidents by driving within the speed limit.Prevent means stop something from happening.","slide":86,"shape":"19","bookPage":"71"},{"text":"6 Many accidents happen when drivers pass other cars without checking their mirrors.Pass means go past somebody or something.","slide":86,"shape":"20","bookPage":"71"},{"text":"7 Many people drive cars to work because it’s more convenient to sit comfortably in your own vehicle.Convenient means easy to use.","slide":86,"shape":"21","bookPage":"71"},{"text":"8 Our city has a lot of traffic problems. To solve some of them, we’re encouraging people to cycle more and drive less.Solve means find a way to fix a problem.","slide":87,"shape":"19","bookPage":"71"},{"text":"a (adj) easy to use or suiting your plans well.a convenient.","slide":91,"shape":"14","bookPage":"71"},{"text":"b (v) to go past somebody or something.b pass.","slide":91,"shape":"16","bookPage":"71"},{"text":"c (v) to hurt or cause physical harm.c injure.","slide":91,"shape":"6","bookPage":"71"},{"text":"d (n) polite behaviour towards somebody.d respect.","slide":92,"shape":"17","bookPage":"71"},{"text":"e (v) to find a way to fix a problem.e solve.","slide":92,"shape":"19","bookPage":"71"},{"text":"f (n) money which has to be paid as punishment for not obeying a law.f fine.","slide":92,"shape":"6","bookPage":"71"},{"text":"g (v) to stop something from happening.g prevent.","slide":93,"shape":"17","bookPage":"71"},{"text":"h (v phr) to fail to obey the rules of a country, state or city.h break the law.","slide":93,"shape":"19","bookPage":"71"},{"text":"1 What are some of the reasons that people cycle in a big city?Possible answer: People may cycle because it is affordable, provides exercise and avoids some traffic delays.","slide":96,"shape":"18","bookPage":"71"},{"text":"2 What are some advantages of cycling to work?Possible answer: For some short journeys, cycling can be quicker than driving, and a bicycle is easier to park.","slide":96,"shape":"20","bookPage":"71"},{"text":"3 What are some problems with cycling to work?Possible answer: Heavy traffic, narrow cycle lanes, bad weather and a lack of secure parking can make cycling difficult.","slide":97,"shape":"19","bookPage":"71"},{"text":"1 What is the goal of the Wheels to Work group?The group wants to make the city more bicycle-friendly and make it easier for people to cycle to work.","slide":100,"shape":"14","bookPage":"72"},{"text":"2a What is the first main issue with cycling to work?The first issue is safety.","slide":100,"shape":"16","bookPage":"72"},{"text":"2b What is the second main issue with cycling to work?The second issue is storage.","slide":100,"shape":"6","bookPage":"72"},{"text":"2c What is the third main issue with cycling to work?The third issue is convenience.","slide":101,"shape":"14","bookPage":"72"},{"text":"1 Most people don’t have bicycles. Do not circle this problem.","slide":104,"shape":"19","bookPage":"72"},{"text":"2 There’s a lot of traffic. Circle this problem.","slide":104,"shape":"20","bookPage":"72"},{"text":"3 There aren’t any cycle lanes in the city. Do not circle this problem.","slide":104,"shape":"21","bookPage":"72"},{"text":"4 The cycle lanes are often too narrow. Circle this problem.","slide":104,"shape":"5","bookPage":"72"},{"text":"5 Cars sometimes drive in the cycle lanes. Circle this problem.","slide":104,"shape":"6","bookPage":"72"},{"text":"6 There’s nowhere to put your bicycle while working. Circle this problem.","slide":104,"shape":"7","bookPage":"72"},{"text":"7 It’s too cold. Do not circle this problem.","slide":104,"shape":"8","bookPage":"72"},{"text":"8 There’s nowhere to shower at work. Do not circle this problem.","slide":105,"shape":"19","bookPage":"72"},{"text":"9 Some people live far away from work. Circle this problem.","slide":105,"shape":"20","bookPage":"72"},{"text":"10 People don’t want to cycle at night. Circle this problem.","slide":105,"shape":"21","bookPage":"72"},{"text":"Recommendations\nPossible results\n1  Fines for driving in cycle lanes\ndrivers avoid hitting cyclists; saves lives\n2  Wider cycle lanes\nmore bicycles can pass at the same time\n3  More cycle lanes on busy streets\nfewer cars hit cyclists; saves lives","slide":107,"shape":"15","bookPage":"72"},{"text":"Recommendations\nPossible results\n4  Bicycle sections in parking garages\nbicycles stay safe and dry while people work\n5  Cycle racks on buses\nno need to cycle at night or in bad weather; people far from work can combine cycling and public transport","slide":108,"shape":"15","bookPage":"72"},{"text":"Possible answer: 7 Look again at sentences 1–10 in Exercise 5. Discuss whether these problems exist in your city or town.Some roads have cycle lanes, but several are narrow. Bicycle parking is available near the station, although there are few secure spaces near smaller workplaces.","slide":112,"shape":"13","bookPage":"73"},{"text":"Explain control.control — to limit or manage somethingExample: We need to control the amount of traffic.","slide":121,"shape":"16","bookPage":"67"},{"text":"Explain figure out.figure out — to understand something or find a solution by thinkingExample: The engineers can figure out how to improve the signals.","slide":121,"shape":"17","bookPage":"67"},{"text":"Explain fixed.fixed — not able to be changedExample: The old lights follow fixed timings.","slide":121,"shape":"18","bookPage":"67"},{"text":"Explain impact.impact — an effect or influenceExample: A crash can have an impact on nearby roads.","slide":122,"shape":"16","bookPage":"67"},{"text":"Explain influence.influence — to affect how somebody acts or thinksExample: Transport costs influence how people travel.","slide":122,"shape":"17","bookPage":"67"},{"text":"Explain serious.serious — important or badExample: Congestion is a serious problem in this city.","slide":122,"shape":"18","bookPage":"67"},{"text":"Explain trouble.trouble — problems or difficultiesExample: A blocked road can cause trouble for other drivers.","slide":123,"shape":"19","bookPage":"67"},{"text":"1 impact — effect","slide":126,"shape":"15","bookPage":"67"},{"text":"2 trouble — problems","slide":126,"shape":"16","bookPage":"67"},{"text":"3 serious — important or bad","slide":127,"shape":"15","bookPage":"67"},{"text":"4 control — to limit something","slide":127,"shape":"16","bookPage":"67"},{"text":"5 fixed — not able to be changed","slide":128,"shape":"17","bookPage":"67"},{"text":"6 influence — to affect how somebody acts or thinks","slide":128,"shape":"18","bookPage":"67"},{"text":"7 figure out — to understand or solve a problem by thinking","slide":128,"shape":"19","bookPage":"67"},{"text":"5  The traffic controllers can figure out the best way to keep everything moving.","slide":131,"shape":"7","bookPage":"67"},{"text":"6  They don’t have to follow the same, fixed timings for the lights all day long.","slide":131,"shape":"8","bookPage":"67"},{"text":"7  What other factors influence how well traffic flows?","slide":131,"shape":"9","bookPage":"67"},{"text":"Which words have the same pronunciation as both noun and verb? control.","slide":133,"shape":"17","bookPage":"67"},{"text":"Which words have the same pronunciation as both noun and verb? influence.","slide":133,"shape":"19","bookPage":"67"},{"text":"Which words have the same pronunciation as both noun and verb? trouble.","slide":133,"shape":"6","bookPage":"67"},{"text":"1 Who has (or had) the most influence on your life?Possible answer: My maths teacher had a huge influence on my life because she helped me become more confident.","slide":135,"shape":"15","bookPage":"68"},{"text":"2 What happened the last time you were in trouble with somebody?Possible answer: I was in trouble with my parents because I stayed out later than we had agreed.","slide":135,"shape":"17","bookPage":"68"},{"text":"Adjective\nComparative form\nSuperlative form\nfast\nfaster\nthe fastest\nsafe\nsafer\nthe safest\ncomfortable\nmore comfortable\nthe most comfortable\nhealthy\nhealthier\nthe healthiest\ncheap\ncheaper\nthe cheapest\nbad\nworse\nthe worst","slide":145,"shape":"14","bookPage":"69"},{"text":"Adjective\nComparative form\nSuperlative form\nthin\nthinner\nthe thinnest\nslow\nslower\nthe slowest\nrelaxing\nmore relaxing\nthe most relaxing\nnoisy\nnoisier\nthe noisiest\ndangerous\nmore dangerous\nthe most dangerous\ndirty\ndirtier\nthe dirtiest","slide":146,"shape":"14","bookPage":"69"},{"text":"1 The most direct route to my office is not always the fastest, because there is often traffic.","slide":149,"shape":"14","bookPage":"69"},{"text":"2 I’m always calmer in a car than in a plane.","slide":149,"shape":"16","bookPage":"69"},{"text":"3 Using mobile phones while driving is the most serious driving safety issue.","slide":150,"shape":"17","bookPage":"69"},{"text":"4 Driving your own car is the most comfortable way to travel.","slide":150,"shape":"19","bookPage":"69"},{"text":"5 If you are in a hurry, it is often faster to cycle than to drive a car.","slide":151,"shape":"17","bookPage":"69"},{"text":"6 Buying a monthly pass is more affordable than paying for every trip.","slide":151,"shape":"19","bookPage":"69"},{"text":"7 In many countries, the most appropriate tip for a taxi driver is 20% of the fare.","slide":151,"shape":"6","bookPage":"69"},{"text":"8 Flying is a lot safer than driving.","slide":151,"shape":"8","bookPage":"69"},{"text":"1 The course was a LOT more challenging than I expected.","slide":156,"shape":"17","bookPage":"70"},{"text":"2 We can see that by FAR the most affordable form of transport is walking.","slide":156,"shape":"18","bookPage":"70"},{"text":"3 The risks of driving a car are con-SID-erably more significant than those of flying.","slide":157,"shape":"17","bookPage":"70"},{"text":"4 For me, flying is MUCH more comfortable than travelling by train.","slide":157,"shape":"18","bookPage":"70"},{"text":"5 Taking a train is DEF-initely more relaxing than driving.","slide":158,"shape":"16","bookPage":"70"},{"text":"6 Using the underground is a LOT faster than travelling by bus at rush hour.","slide":158,"shape":"17","bookPage":"70"},{"text":"7 Driving is con-SID-erably more expensive than walking.","slide":158,"shape":"18","bookPage":"70"},{"text":"8 Cycling is abso-LUTE-ly the healthiest form of transport.","slide":159,"shape":"17","bookPage":"70"},{"text":"Possible answer: 12 Make a list of as many forms of transport as you can think of.plane, helicopter, bicycle, boat, car, electric car, bus, coach, lorry, taxi, train, underground train, tram.","slide":166,"shape":"13","bookPage":"70"},{"text":"Possible answer: 13 Make a comparison.A car is faster than a bicycle.","slide":168,"shape":"16","bookPage":"70"},{"text":"Possible answer: 13 Make a comparison.A bicycle is cheaper to use than a bus.","slide":168,"shape":"17","bookPage":"70"},{"text":"Possible answer: 13 Make a comparison.A bus is more comfortable than a bicycle in heavy rain.","slide":168,"shape":"18","bookPage":"70"},{"text":"Possible answer: 13 Finish with a superlative.For very short journeys, walking is the simplest choice.","slide":168,"shape":"19","bookPage":"70"},{"text":"The bus stop near my school is often blocked. Parents park in front of it at eight o’clock. The town could add a no-parking sign. This could help buses stop safely.","slide":172,"shape":"6","bookPage":null},{"text":"Walking is slower than cycling to our sports centre. However, the walking route has fewer cars. It is also the safest route for my younger brother. We usually walk together.","slide":172,"shape":"9","bookPage":null},{"text":"11. Why does the host cite the urban-population forecast?\nA. To warn that traffic pressure could grow.\nB. To compare urban and rural transport costs.\nC. To show that traffic is already easing.","slide":178,"shape":"5","bookPage":null},{"text":"12. What does Mark identify as the main cause of severe city traffic?\nA. Most city roads have been closed\nB. Private cars often carry only one or two people\nC. Buses carry too few passengers","slide":179,"shape":"5","bookPage":null},{"text":"1. The host says that traffic in cities has increased substantially over the past century.\nAnswer: TRUE","slide":182,"shape":"5","bookPage":null},{"text":"2. The discussion predicts that 70 percent of the world's population will live in rural areas by 2050.\nAnswer: FALSE","slide":182,"shape":"8","bookPage":null},{"text":"Road repairs have changed my father’s journey. He now uses the underground from a different station. It is more expensive than the bus, but it is faster in the morning. He plans his route the night before.","slide":187,"shape":"6","bookPage":null},{"text":"The bus stop outside the hospital is the most convenient place to get off. It is closer than the underground station. The short walk has a clear crossing. I would tell the visitor to use that stop.","slide":188,"shape":"6","bookPage":null},{"text":"Problems\nProposed solutions\nPredicted results\nStorage: no safe place for bicycles at work.\nBicycle sections in parking garages.\nBicycles stay safe and dry.\nConvenience:\nlong journeys, darkness or bad weather.\nCycle racks on buses.\nPeople combine cycling and public transport, avoiding difficult parts of the journey.","slide":194,"shape":"15","bookPage":"74"},{"text":"Possible answer: 2 Compare your answers to Exercise 1. Add necessary information: bicycle sections in garages address storage and keep bicycles safe and dry.","slide":197,"shape":"15","bookPage":"74"},{"text":"Possible answer: 3 Think about transport problems in your city or country. Possible problems: rush-hour congestion; unreliable buses; narrow cycle lanes; limited accessible transport; lack of safe bicycle parking.","slide":199,"shape":"13","bookPage":"75"},{"text":"Problem\nProposed solutions\nPredicted results\nHeavy commuter traffic\nImprove rail links and bus connections.\nMore commuters could use public transport.\nThe same problem\nHelp colleagues share car journeys.\nFewer separate cars would travel into the centre.\nThe same problem\nImprove cycle access to stations.\nMore people could combine cycling and train travel.","slide":202,"shape":"16","bookPage":"75"},{"text":"Possible answer: 5 What do you predict the results would be of each solution? Which solution is best? I would start by improving bus connections to the railway station. This could help commuters sooner than building a new railway. It would need reliable timetables and enough services.","slide":204,"shape":"17","bookPage":"75"},{"text":"Possible answer: Compare another option. A new railway could carry many more people, but it would take more time and money to build.","slide":204,"shape":"18","bookPage":"75"},{"text":"Speaker A believes eating while driving can be dangerous. Not selected.","slide":206,"shape":"14","bookPage":"76"},{"text":"Speaker B believes eating while driving can be dangerous. Selected.","slide":207,"shape":"14","bookPage":"76"},{"text":"Speaker C believes eating while driving can be dangerous. Selected.","slide":208,"shape":"14","bookPage":"76"},{"text":"Speaker D believes eating while driving can be dangerous. Selected.","slide":209,"shape":"14","bookPage":"76"},{"text":"1 I don’t think the government should do anything about it.","slide":211,"shape":"16","bookPage":"76"},{"text":"2 I think it would be better if they closed drive-through restaurants.","slide":211,"shape":"17","bookPage":"76"},{"text":"3 I think it would be much better if drivers weren’t allowed to eat or drink while they drive.","slide":211,"shape":"18","bookPage":"76"},{"text":"4 The best thing would be to have more cameras on the roads to record what drivers are doing.","slide":212,"shape":"20","bookPage":"76"},{"text":"5 I’d suggest that the police give the drivers points on their licence.","slide":212,"shape":"21","bookPage":"76"},{"text":"b  Personally, I eat fast food in my car a few times a week and I’ve never had an\naccident.  Recommendation 1: I don’t think the government should do anything about it.","slide":215,"shape":"7","bookPage":"77"},{"text":"c  The reason for this is the police can check the videos to see who’s eating, who’s\ntexting and so on.  Recommendation 4: The best thing would be to have more cameras on the roads to record what drivers are doing.","slide":215,"shape":"8","bookPage":"77"},{"text":"d  This is because they only encourage drivers to buy food and eat it while they drive. \nRecommendation 2: I think it would be better if they closed drive-through restaurants.","slide":215,"shape":"9","bookPage":"77"},{"text":"Possible answer: 4 What is your opinion of eating while driving? Give recommendations and examples.A: I’d suggest that drivers stop somewhere suitable before eating. This is because holding food could distract them from the road.","slide":217,"shape":"13","bookPage":"77"},{"text":"Possible answer: B: I agree. The best thing would be to leave enough time for a break. For example, a driver could eat before starting a long journey.","slide":217,"shape":"14","bookPage":"77"},{"text":"Possible answer: A: That sounds practical. From the example in the recording, even a sudden spill can cause a serious problem.","slide":217,"shape":"15","bookPage":"77"},{"text":"Possible answer: 1 Look at the table you created in Exercises 4 and 5. Review notes and add information: include a clearly stated transport problem, more than one possible solution, and a predicted result for each solution.","slide":221,"shape":"14","bookPage":"77"},{"text":"Possible answer: 2 Plan an introduction: explain the transport problem, why it interests you, and that you will discuss problems then solutions.Hello, everybody. Thank you for being here today. I’m going to talk about rush-hour traffic between our town and the city centre. This interests me because my family makes this journey every day. First, I’ll explain the problems, then I’ll suggest some solutions.","slide":223,"shape":"13","bookPage":"78"},{"text":"1 Getting to work on time is considerably the more difficult than it used to be.Correct: Getting to work on time is considerably more difficult than it used to be.","slide":227,"shape":"15","bookPage":"78"},{"text":"2 Many people believe travelling by private car is more convenient then go by bus.Correct: Many people believe travelling by private car is more convenient than going by bus.","slide":227,"shape":"16","bookPage":"78"},{"text":"Possible answer: 5 For each proposed solution, make notes about how you will expand on your idea with reasons and examples from personal experience or knowledge. Recommendation: I’d like to see more buses connecting our town with the railway station. Reason: This is because many people drive to the city when they cannot easily reach the station. Example: From my own experience, missing one connecting bus can make the whole journey much longer.","slide":230,"shape":"19","bookPage":"78"},{"text":"Possible answer: 6 Work in small groups. Take turns practising your presentations. Take notes during the discussion. Use your notes to give feedback to each other to improve your presentations.Feedback on the presentationYour transport problem is clear, and you compare the options well. Add one example to explain why the bus connection would help commuters.","slide":233,"shape":"14","bookPage":"78"},{"text":"Hello, everyone. Thank you for being here today. I’m going to talk about rush-hour trafficbetween our town and the city centre. I’m interested in this issue because several peoplein my family make this journey every day. First, I’ll explain the problems, then I’ll suggestpossible solutions.","slide":235,"shape":"13","bookPage":"79"},{"text":"The main problem is that too many private cars carry only one or two people. Busesoften wait in the same traffic, so taking the bus can be much slower than people expect.For people who live near a station, travelling by train may be more convenient, butreaching the station is sometimes difficult.","slide":236,"shape":"14","bookPage":"79"},{"text":"I’d suggest that the council improve bus connections to the railway station. The reasonfor this is that a reliable connection could make the whole journey easier than driving.From my own experience, a long wait between a bus and a train can discourage peoplefrom using public transport.","slide":237,"shape":"14","bookPage":"79"},{"text":"Another solution would be to help colleagues share their journeys. Businesses could putinterested staff in contact with others who live nearby. This could be cheaper for eachtraveller and would mean fewer separate cars travelling into the city. For example, threecolleagues could travel in one car instead of three.","slide":238,"shape":"14","bookPage":"79"},{"text":"Building a new railway link could carry more people in the long term, but it would costmore and take longer than improving existing connections. In my opinion, we shouldbegin with reliable bus connections and voluntary car sharing, then compare the resultsbefore planning larger changes.","slide":239,"shape":"14","bookPage":"79"},{"text":"To conclude, our town needs practical alternatives to driving alone. Better connectionsand shared journeys could reduce traffic and make commuting more convenient. Theseproposals would need suitable timetables and support from local employers. Thank youfor listening.","slide":240,"shape":"13","bookPage":"79"},{"text":"The speaker introduces the topic, explains the problems, compares solutions and\nconcludes with a recommendation.","slide":241,"shape":"7","bookPage":"79"},{"text":"The presentation uses comparatives such as slower than, more convenient,\ncheaper, more and longer than.","slide":241,"shape":"10","bookPage":"79"},{"text":"Reasons and examples explain how the proposals would help.","slide":241,"shape":"13","bookPage":"79"},{"text":"The council should improve the crossing near our library. Many children use it after school. For example, a crossing officer could stop cars while groups cross. I think this is a practical safety change.","slide":245,"shape":"6","bookPage":null},{"text":"I recommend an extra bus at the end of the school day. Many students stand at the stop for a long time. The new service could take passengers home earlier. It would also reduce the queue at the stop.","slide":246,"shape":"6","bookPage":null}];
